#include "chimera/mobile/package_fabric.hpp"
namespace chimera::mobile {
PackageFormat PackageFabric::detect_format(const std::string& p){auto dot=p.rfind('.');if(dot==std::string::npos)return PackageFormat::Unknown;auto e=p.substr(dot+1);if(e=="deb")return PackageFormat::Deb;if(e=="rpm")return PackageFormat::Rpm;if(e=="apk")return PackageFormat::ApkAndroid;if(e=="flatpak")return PackageFormat::Flatpak;if(e=="snap")return PackageFormat::Snap;if(e=="AppImage"||e=="appimage")return PackageFormat::AppImage;if(e=="pkg")return PackageFormat::Native;return PackageFormat::Unknown;}
bool PackageFabric::compatible(PackageFormat f,PackageTarget t){if(t==PackageTarget::AndroidContainer)return f==PackageFormat::ApkAndroid;if(t==PackageTarget::SwiftRuntime)return f==PackageFormat::SwiftPM||f==PackageFormat::GitSource;if(f==PackageFormat::Deb||f==PackageFormat::Dpkg||f==PackageFormat::Apt)return t==PackageTarget::Arm64||t==PackageTarget::HostTool;if(f==PackageFormat::Rpm||f==PackageFormat::Dnf||f==PackageFormat::Yum)return t==PackageTarget::Arm64||t==PackageTarget::HostTool;if(f==PackageFormat::Apk)return t==PackageTarget::Arm64;return t==PackageTarget::Arm64||t==PackageTarget::ChimeraNBit;}
bool PackageFabric::validate(const PackageRecord&p)const{return !p.name.empty()&&!p.version.empty()&&!p.architecture.empty()&&!p.sha256.empty()&&p.signature==SignatureState::Verified&&compatible(p.format,p.target);}
InstallPlan PackageFabric::plan(const PackageRecord&p,const std::vector<std::string>&d)const{InstallPlan x{p,d,true,true};if(p.privileged)x.sandboxed=false;return x;}
}
